  it("invert(x - 3)", () => {
    const x = new Sym('x');
    const v1 = x;
    expect(sympyStr([at(invertEquation(add(Rational.of(-3n, 1n, { gcd: 1n }), x), [], { integerPower: false }), 0), v1], 't')).toBe('(3, x)');
  });
  it("invert(3)", () => {
    const v1 = Rational.of(3n, 1n, { gcd: 1n });
    expect(sympyStr([v1, at(invertEquation(v1, [], { integerPower: false }), 1)], 't')).toBe('(3, 0)');
  });
